create extension if not exists pgcrypto;

create table if not exists public.ax_pbl_tasks (
  code text primary key,
  name text not null,
  type text,
  score numeric,
  grade text,
  rank_text text,
  recommended_stage text,
  status text,
  departments text,
  proposers text,
  request_count integer,
  evidence text,
  prerequisites text,
  created_at timestamptz not null default now()
);

