('C36','장비 제조사 기술 업데이트 모니터링','워크플로/알림',66.0,'C','40.0','2단계 핵심 제조사 파일럿','신규개발 후보','설비기술팀','이동화',1,'정기 웹 모니터링과 요약은 가능하나 제조사별 페이지 구조, 정보 신뢰성, 변경 탐지 유지보수가 필요하다. 직접 업무효과는 중간 수준이다.','장비-제조사-URL 목록 · 기술정보 키워드 · 공식출처 우선순위 · 중복/오탐 필터 · 월 2회 검토 담당자'),
('C43','CCTV Vision 기반 PPE·위험구역 안전 모니터링','Vision/OCR',66.0,'C','40.0','3단계 단일 위험시나리오 제한 PoC','신규개발 후보','안전팀','박신명',1,'24시간 안전감시 효과는 크지만 CCTV Vision은 촬영환경·개인정보·오탐/미탐·실시간 인프라 난도가 매우 높다. 사람 확인 없는 경보...','영상 개인정보 영향평가와 고지 · 카메라 사각/조명 진단 · PPE·구역 라벨 데이터 · 오탐/미탐 목표 · 안전담당자 확인·경보 절차'),
('C39','화재·안전 위험요인 데이터 분석 및 예방대책','분석/의사결정 지원',65.0,'C','43.0','3단계 전문가 검토형 위험평가 PoC','신규개발 후보','설비기술팀, 안전팀','도인훈, 박신명',2,'안전 효과는 최상이나 사고 데이터 희소성, 위험도 점수의 책임과 오판 비용이 크다. AI 자동판정이 아닌 사례검색·체크리스트·근거 제시가 ...','사고/아차사고/점검 이력 · 기계·전기·공정·환경 위험분류 · 법정 기준 · 위험성평가 전문가 승인 · 점수 설명·감사로그'),
('C33','시험계획 최적화 및 물성예측·레시피 시뮬레이션','예측/최적화',64.0,'C','44.0','3단계 데이터 품질진단 후 연구 PoC','신규개발 후보','기술연구소','윤종한',2,'시험 감소 잠재효과와 AI 적합성은 높으나 설명상 축적 데이터의 규모·정합성이 확인되지 않았다. 예측 불확실성을 표시하고 실제 시험을 대체...','실험조건·레시피·공정조건·물성 결과 통합 · 결측/단위 정리 · 최소 표본수 진단 · 홀드아웃 검증 · 예측구간과 연구원 승인'),
('C35','수입화물 입항일정 통합조회·알림','워크플로/알림',64.0,'C','44.0','2단계 주요 선사 파일럿','신규개발 후보','관리부문','손종협',1,'분산된 선사 조회를 통합하면 편의성이 있으나 선사별 API·웹 구조와 포워더 데이터 접근성이 불명확하다. 기술적 지속관리 비용을 반영했다.','B/L·컨테이너 번호 관리 · 주요 선사/API 목록 · 포워더 협의 · 일정변경 감지 · 조회 실패 예외 알림'),
('C27','PLC 프로그램·전기도면 해석 및 설명서 생성','분석/의사결정 지원',61.0,'C','46.0','3단계 샌드박스 PoC','신규개발 후보','설비기술팀','이희문, 차영남',2,'PLC·도면 이해는 활용가치가 있으나 포맷 다양성, 프로그램 맥락, 오해석에 따른 설비안전 위험이 크고 자료가 없다. 설명 보조로만 제한해...','대표 PLC 소스/전기도면과 정답 설명 · 제조사·버전 정보 · 읽기전용 샌드박스 · 전기·제어 전문가 검증 · 제어코드 자동반영 금지'),
('C41','건강검진·근태 기반 보건상담 대상 알림','워크플로/알림',59.0,'D','47.0','3단계 개인정보 영향평가 후 제한 파일럿','신규개발 후보','관리부문','김혜민',1,'보건 선제관리 효과는 있으나 건강정보와 근태를 결합하는 민감정보 처리, 선정 오류·차별 위험이 크다. 자동 선정이 아닌 보건전문가 검토 후...','법적 근거·명시적 동의 · 최소수집/접근통제 · 선정 기준의 의학적 검토 · 보건담당자 승인 · 안전한 알림과 이의제기 절차'),
('C16','거래명세서 OCR 기반 ERP 구매입고·구매신청 자동화','Vision/OCR',94.0,'S','확산','완료기능 검증 후 1단계 전사 확산','완료/확산 후보','생산기술3팀, 설비기술팀','김성환, 차영남, 최재림',4,'동일 업무가 여러 팀에서 반복 제안됐고 68·69는 제작 완료이며 자료 링크도 있다. 검증된 기능을 공통 컴포넌트로 확산할 가치가 매우 높다.','완료 기능 정확도·예외율 검증 · 공급사별 양식 샘플 · 품목/거래처 마스터 매칭 · 중복입고 방지 · ERP 반영 전 사용자 확인')
on conflict (code) do update set
  name=excluded.name,
  type=excluded.type,
  score=excluded.score,
  grade=excluded.grade,
  rank_text=excluded.rank_text,
  recommended_stage=excluded.recommended_stage,
  status=excluded.status,
  departments=excluded.departments,
  proposers=excluded.proposers,
  request_count=excluded.request_count,
  evidence=excluded.evidence,
  prerequisites=excluded.prerequisites;

create table if not exists public.ax_pbl_submissions (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  task_code text not null references public.ax_pbl_tasks(code),
  task_name text not null,
  department text not null,
  writer_name text not null,
  written_date date not null,
  process_owner text not null,

  business_purpose text not null,
  current_usage text not null,
  target_users text not null,
  related_systems text,
  major_input_data text not null,
  major_outputs text not null,

  usage_frequency text,
  time_before numeric,
  time_after numeric,
  error_reduction text,
  satisfaction numeric check (satisfaction is null or satisfaction between 1 and 5),
  field_feedback text,
  quantitative_effect text,
  qualitative_effect text,

  required_values_rule text,
  calculation_rule text,
  decision_rule text,
  approval_rule text,
  permission_rule text,
  error_handling_rule text,
  output_format_rule text,

  source_data text,
  input_location_fields text,
  linked_target text,
  security_permission text,
  attachment_required text,
  api_sync_required text,

  reusable_other_departments boolean not null default false,
  common_module_possible boolean not null default false,
  standard_form_reusable boolean not null default false,
  operational_conversion_possible boolean not null default false,
  integration_candidate boolean not null default false,

  problems text,
  additional_requests text,
  verification_items text,
  next_step text,

  business_effect_level text not null check (business_effect_level in ('높음','보통','낮음')),
  reusability_level text not null check (reusability_level in ('높음','보통','낮음')),
  integration_priority text not null check (integration_priority in ('상','중','하')),
  final_decision text not null check (final_decision in ('통합 MVP 후보','보류','추가 검토')),

  sheet_sync_status text not null default 'pending' check (sheet_sync_status in ('pending','success','failed','skipped')),
  sheet_synced_at timestamptz,
  sheet_sync_error text,
  user_agent text,
  ip_hash text
);

create index if not exists idx_ax_pbl_submissions_created_at on public.ax_pbl_submissions(created_at desc);
create index if not exists idx_ax_pbl_submissions_task_code on public.ax_pbl_submissions(task_code);
create index if not exists idx_ax_pbl_submissions_decision on public.ax_pbl_submissions(final_decision);

alter table public.ax_pbl_tasks enable row level security;
alter table public.ax_pbl_submissions enable row level security;

drop policy if exists "public read task master" on public.ax_pbl_tasks;
create policy "public read task master" on public.ax_pbl_tasks
  for select to anon, authenticated using (true);

drop policy if exists "public insert submissions" on public.ax_pbl_submissions;
create policy "public insert submissions" on public.ax_pbl_submissions
  for insert to anon, authenticated with check (true);

drop policy if exists "public read submissions for p0 admin" on public.ax_pbl_submissions;
create policy "public read submissions for p0 admin" on public.ax_pbl_submissions
  for select to anon, authenticated using (true);

comment on table public.ax_pbl_submissions is 'AX-PBL 과제별 실제 사용 결과·업무규칙 수집 원장. P0는 로그인 없이 작성 가능하므로 운영 전 관리자 인증과 스팸 방지 정책 필요.';
